import {openPdf} from './pdf-client.js';
const STORE='aeromission-ops-3',PREVIOUS='aeromission-rebuilt-v2';
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():('am-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12));
const blank=()=>({missions:[],jobs:[],fleet:[],logbook:[],selected:null,view:'dashboard',tasks:[],settings:{vatsim_cid:'',access_pin:'',home_base:'',units:'IMPERIAL',mx_default:'OK',age_influence:true},live:null,events:[]});
let state;try{const prev=JSON.parse(localStorage.getItem(PREVIOUS)||'null'),v=JSON.parse(localStorage.getItem(STORE)||'null');state={...blank(),...(v||prev||{}),settings:{...blank().settings,...((v||prev)?.settings||{})}}}catch{state=blank()}
function migrateState(){for(const k of ['missions','jobs','fleet','logbook','tasks','events'])if(!Array.isArray(state[k]))state[k]=[];
 for(const m of state.missions){if(!Array.isArray(m.legs))m.legs=[];if(!Array.isArray(m.airport_briefings))m.airport_briefings=[];if(!Array.isArray(m.maintenance))m.maintenance=[];if(!m.research_audit||typeof m.research_audit!=='object')m.research_audit={};m.mx_level=m.mx_level||'OK';
 for(const l of m.legs){l.departure_utc=l.departure_utc||l.departure||null;l.arrival_utc=l.arrival_utc||l.arrival||null;l.planning=l.planning||null;l.planning_status=l.planning_status||(l.planning?'SIM ESTIMATE':'PENDING')}
 for(const a of m.airport_briefings){a.fbos=Array.isArray(a.fbos)?a.fbos:[];a.fuel=Array.isArray(a.fuel)?a.fuel:[];a.sources=Array.isArray(a.sources)?a.sources:[];a.runways=Array.isArray(a.runways)?a.runways:(a.runways?[String(a.runways)]:[]);a.frequencies=Array.isArray(a.frequencies)?a.frequencies:[];for(const f of a.fuel)if(f.price!==undefined&&f.published_price===undefined){f.estimated_price=f.price;f.published_price=null;f.price_status='MIGRATED UNVERIFIED PRICE — NOT A LIVE QUOTE'}}
 m.manifest=Array.isArray(m.manifest)?m.manifest.map(x=>typeof x==='string'?{name:x,role:''}:x?.text?{name:x.text,role:''}:x):[];m.cargo=Array.isArray(m.cargo)?m.cargo.map(x=>typeof x==='string'?{description:x,weight_lb:null}:x?.text?{description:x.text,weight_lb:null}:x):[];m.documents=Array.isArray(m.documents)?m.documents.map(x=>typeof x==='string'?x:x?.text||'Migrated document'):[];
 }
 for(const a of state.fleet){a.model=a.model||a.type||'';a.mx_level=a.mx_level||({'AVAILABLE':'OK','MAINTENANCE':'BAD','RESTRICTED':'BAD'}[a.status]||'OK');a.registration_status=a.registration_status||'UNVERIFIED (IMPORTED)';a.sources=Array.isArray(a.sources)?a.sources:[]}
}
migrateState();
for(const t of state.tasks||[]){if(t.state==='RUNNING'&&!t.job_id){t.state='QUEUED';t.error='Launch was interrupted; restarting.'}}
let health={ok:false,aiConfigured:false,pinRequired:false},polling=false,vatsimBusy=false;const statusName={queued:'QUEUED',in_progress:'RESEARCHING',research:'RESEARCHING',interpretation:'INTERPRETING',completed:'COMPLETE'};
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=u=>{try{const a=new URL(u);return ['https:','http:'].includes(a.protocol)?esc(a.href):'#'}catch{return '#'}};
let storageWarned=false;const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(state))}catch(e){if(!storageWarned){storageWarned=true;toast('Browser storage is blocked or full. Enable site data storage or export a backup; unsaved changes may not persist.')}}};
const fmt=x=>{if(!x)return '—';const d=new Date(x);return Number.isFinite(+d)?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:'UTC'})+' UTC':String(x)};
const nfmt=(v,unit='')=>v===null||v===undefined||v===''?'—':Number.isFinite(+v)?Number(v).toLocaleString(undefined,{maximumFractionDigits:1})+(unit?' '+unit:''):String(v);
const tiny=s=>String(s||'').slice(0,100);
function toast(text){const x=document.createElement('div');x.className='toast';x.textContent=text;document.body.append(x);setTimeout(()=>x.remove(),6500)}
function event(text,level='INFO'){state.events.unshift({at:new Date().toISOString(),text,level});state.events=state.events.slice(0,80);save()}
async function api(path,body,options={}){let r;try{r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(state.settings.access_pin?{'X-App-Pin':state.settings.access_pin}:{})},body:body===undefined?undefined:JSON.stringify(body),...options})}catch(e){throw Error('Network unavailable. Check Render deployment or internet: '+e.message)}let text=await r.text(),d;try{d=JSON.parse(text)}catch{throw Error(`Server returned ${text.trim().startsWith('<')?'HTML instead of JSON (possibly an outdated deploy or wrong endpoint)':'an unreadable response'} [HTTP ${r.status}]`)}if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);return d}
const active=()=>state.missions.find(x=>x.id===state.selected)||state.missions[0];
const known=()=>state.tasks.filter(t=>['QUEUED','RUNNING'].includes(t.state));
const pill=(text,type='')=>`<span class="pill ${type}">${esc(text||'UNKNOWN')}</span>`;
const btn=(a,text,kind='secondary',attrs='')=>`<button type="button" class="btn ${kind}" data-action="${a}" ${attrs}>${text}</button>`;
const box=(name,body,extra='')=>`<section class="panel ${extra}"><div class="panel-head"><h3>${name}</h3></div>${body}</section>`;
const item=(a,b)=>`<div class="data-pair"><span>${esc(a)}</span><strong>${b===null||b===undefined||b===''?'—':esc(b)}</strong></div>`;
const lines=xs=>(Array.isArray(xs)&&xs.length)?`<ul class="clean-list">${xs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<span class="muted">Not reported</span>';
const cards=(arr,render)=>arr.map(render).join('');
const nav=[['dashboard','◫','Overview'],['builder','✦','Mission Builder'],['jobs','▥','Job Board'],['dispatch','◈','Dispatch'],['fleet','✈','Fleet / MX'],['flight','◉','VATSIM / Live'],['logbook','▤','Logbook'],['settings','⚙','Settings']];
function background(){const tasks=state.tasks.slice(-20).reverse(),running=known().length;return `<div class="task-panel"><div class="task-top"><strong>AI OPERATIONS QUEUE</strong><span class="muted">${running} active / queued · jobs persist through page reload</span></div>${tasks.length?`<div class="task-grid">${tasks.map(t=>`<div class="task ${t.state==='ERROR'?'task-error':''}"><div class="task-name">${esc(t.label||t.kind.toUpperCase())}</div>${pill(t.state==='RUNNING'?statusName[t.phase]||'WORKING':t.state,t.state==='ERROR'?'bad':t.state==='DONE'?'good':'pending')}${t.state==='ERROR'?`<div class="task-err" title="${esc(t.error)}">${esc(t.error)}</div><button class="minor-btn" data-retry="${esc(t.id)}">Retry</button>`:''}</div>`).join('')}</div>`:'<div class="muted">No jobs yet. AI runs web research, then interprets it into Dispatch data.</div>'}</div>`}
function layout(){const titles={dashboard:'Operations overview',builder:'Mission builder',jobs:'Assignment desk',dispatch:'Dispatch release',fleet:'Fleet & maintenance',flight:'VATSIM flight tracking',logbook:'Flight logbook',settings:'System settings'};$('#app').innerHTML=`<div class="shell"><aside class="side"><div class="logo"><span class="logo-icon">✈</span><div><strong>AeroMission</strong><small>OPS / AI CONTROL 3.0</small></div></div><nav>${nav.map(([key,icon,label])=>`<button data-nav="${key}" class="${state.view===key?'on':''}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')}</nav><div class="side-foot">FLIGHT SIMULATION PLATFORM<br>AI-native • iPad + desktop</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">AEROMISSION OPS / SIMULATION OPERATIONS</div><h1>${titles[state.view]}</h1></div><div class="top-status">${pill(health.aiConfigured?'AI ENABLED':'AI KEY REQUIRED',health.aiConfigured?'good':'bad')}${pill(state.settings.vatsim_cid?'VATSIM CID SET':'VATSIM NOT SET',state.settings.vatsim_cid?'neutral':'pending')}</div></header><div class="workspace"><div id="tasks-mount">${background()}</div><div id="view-mount">${views[state.view]?.()||views.dashboard()}</div></div></main></div>`;bind()}
function updateTasks(){const x=$('#tasks-mount');if(x)x.innerHTML=background();bindTasks();const count=known().length;document.title=`${count?`(${count}) `:''}AeroMission Ops 3.0`}
function updateView(){if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;const v=$('#view-mount');if(v){v.innerHTML=views[state.view]();bindView()}}
function missionTable(arr){return arr.length?`<div class="scroll"><table><thead><tr><th>Mission / brief</th><th>Route</th><th>Aircraft / registration</th><th>MX</th><th>Status</th><th></th></tr></thead><tbody>${[...arr].reverse().map(m=>`<tr><td><b>${esc(m.code)}</b><small>${esc(m.title)}</small></td><td>${esc((m.legs||[]).map(l=>l.origin).slice(0,1).concat((m.legs||[]).map(l=>l.destination)).join(' → '))}</td><td>${esc(m.aircraft)}<small>${esc(m.registration)}</small></td><td>${pill(m.mx_level||'OK')}</td><td>${pill(m.status||'PLANNING','pending')}</td><td><button class="small-btn" data-select-mission="${esc(m.id)}">Open</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No AI missions have been created yet.</div>'}
function dashboard(){const m=active(),jobs=state.jobs.filter(x=>x.status==='AVAILABLE').length;return `<div class="hero"><div><div class="eyebrow">CREW OPERATIONS / GLOBAL</div><h2>Realistic missions.<br><em>Research-backed dispatch.</em></h2><p>AI mission design, registration verification, simulated fleet reliability, airport intelligence and live VATSIM observations in one workspace.</p></div><div>${btn('go-builder','Build an AI mission →','primary')}</div></div><div class="metrics">${[['Saved missions',state.missions.length],['Open assignments',jobs],['Fleet profiles',state.fleet.length],['VATSIM observations',state.logbook.length]].map(([a,b])=>`<div class="metric"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><h2 class="section-title">Recent mission files</h2>${box('Dispatch-ready workspace',missionTable(state.missions))}${m?`<div class="two-col spaced">${box('Selected operation',`<h3 class="big-title">${esc(m.title)}</h3><p>${esc(m.mission_profile||m.description||'')}</p>${m.warnings?.length?`<div class="notice">${esc(m.warnings.join(' | '))}</div>`:''}${item('Mission',m.code)}${item('Aircraft',m.aircraft+' / '+m.registration)}${btn('go-dispatch','Open full dispatch','primary')}`)}${box('Research completeness',progressReport(m))}</div>`:''}`}
function progressReport(m){const airports=m.airport_briefings||[],all=(m.legs||[]).length;return `<div class="numbers">${pill(`${airports.filter(x=>x.status==='RESEARCHED').length}/${airports.length} AIRPORTS RESEARCHED`,airports.every(x=>x.status==='RESEARCHED')?'good':'pending')}${pill(`${m.legs.filter(x=>x.planning).length}/${all} LEGS PLANNED`)}${pill(`${m.maintenance?.length||0} DEFECTS`)}${pill(m.aircraft_identity?.registration_status||m.aircraft_identity?.verification||'AIRCRAFT PENDING')}</div><p class="muted">Unknown fuel prices remain unquoted; AI numerical estimates are labeled as simulation only.</p>`}
function builder(){return `<div class="two-col builder-grid"><section class="panel"><div class="panel-head"><h3>AI mission generator</h3>${pill('AI REQUIRED','neutral')}</div><p class="muted">You can leave every preference blank. AI will invent a mission profile, select a plausible aircraft, build an itinerary and research registration identity.</p><form id="mission-form"><div class="form-grid"><label>Mission type <select name="type"><option value="">AI DECIDES</option>${['Executive charter','Cargo / special logistics','Medical transport','Government / NGO','Scientific / survey','Ferry / reposition','Tourism','Humanitarian','Emergency support','Military contractor'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Aircraft type / ICAO <input name="aircraft" placeholder="Blank = AI finds a real aircraft"></label><label>Saved fleet aircraft <select id="fleet-select" name="fleet_registration"><option value="">AI DECIDES / NOT SELECTED</option>${state.fleet.map(a=>`<option value="${esc(a.registration)}">${esc(a.registration)} / ${esc(a.model||a.icao_type||a.manufacturer)}</option>`).join('')}</select></label><label>Registration <input name="registration" placeholder="Blank = AI researches a matching tail"></label><label>Starting region / airport <input name="starting_point" value="${esc(state.settings.home_base||'')}" placeholder="Blank = global / ICAO, city or country"></label><label>ICAO route (optional) <input name="route" placeholder="LFBO GOBD SOCA or blank"></label><label>Leg count <select name="leg_count"><option value="">AI DECIDES</option>${[1,2,3,4,5,6].map(i=>`<option value="${i}">${i} ${i===1?'leg':'legs'}</option>`).join('')}</select></label><label>Difficulty <select name="difficulty"><option value="">ALL LEVELS / AI DECIDES</option><option>EASY</option><option>MODERATE</option><option>HARD</option><option>VERY DEMANDING</option></select></label><label>Maintenance condition <select name="mx_level">${['GOOD','OK','BAD'].map(x=>`<option ${x===state.settings.mx_default?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="check"><input type="checkbox" name="age_influence" ${state.settings.age_influence?'checked':''}> Aircraft age affects simulated maintenance and INOP scenarios</label><label class="block-label">Additional mission instructions <textarea name="notes" rows="4" placeholder="Examples: island medevac; older King Air; wet runway; VIP with overnight layover; polar research"></textarea></label><div class="row"> <button class="btn primary" type="submit">✦ Generate AI Mission</button><span class="muted">Research runs in the background; no short browser timeout.</span></div></form></section>${box('Generation pipeline',`<ol class="steps"><li><b>AI creates mission concept</b><span>Geography, client backstory, tasking, aircraft, route, manifest, constraints</span></li><li><b>Registration is researched</b><span>Type-to-tail match with sources and explicit verification state</span></li><li><b>Age and condition inform MX</b><span>Aircraft-specific MEL / CDL / INOP and MSFS cockpit actions</span></li><li><b>Airports and legs enriched</b><span>Runways, operators/FBOs, fuel supply/prices, weather, estimated fuel/TOLD/W&B</span></li><li><b>Controlled simulation package</b><span>Multi-page PDF, leg sheets, airport briefings and discrepancies</span></li></ol><div class="notice">Verified public facts are differentiated from AI-generated scenarios and estimates. No fictitious "approved" dispatch records.</div>`)}</div><h2 class="section-title">Your mission library</h2>${box('Saved missions',missionTable(state.missions))}`}
function jobs(){return `<div class="hero mini"><div><div class="eyebrow">GLOBAL ASSIGNMENT DISCOVERY</div><h2>AI-generated opportunities</h2><p>Research-informed mission ideas, not the same fixed routes every time.</p></div>${btn('generate-jobs','Refresh AI job board →','primary')}</div><div class="panel"><form id="job-form" class="job-filters"><label>Starting region<input name="starting_point" value="${esc(state.settings.home_base||'')}" placeholder="Worldwide or ICAO / city"></label><label>Mission class<select name="type"><option value="">ALL TYPES</option><option>CARGO</option><option>CHARTER</option><option>MEDICAL</option><option>SPECIAL OPERATIONS</option><option>POSITIONING</option></select></label><label>Aircraft<input name="aircraft" placeholder="Any"></label><label>Difficulty<select name="difficulty"><option value="">ALL LEVELS</option><option>EASY</option><option>MODERATE</option><option>HARD</option></select></label><label>MX<select name="mx_level"><option value="">ANY</option><option>GOOD</option><option>OK</option><option>BAD</option></select></label></form></div><div class="job-layout"><div class="job-list">${state.jobs.length?state.jobs.map(j=>`<article class="panel job-tile"><div class="row spread">${pill(j.type)}${pill(j.difficulty)}</div><h3>${esc(j.title)}</h3><div class="route-line">${esc(j.route?.join(' → '))}</div><p>${esc(j.description)}</p>${item('Aircraft',j.aircraft)}${item('Maintenance',j.mx_level)}${btn(`accept:${j.id}`,'Generate full mission from this job',j.status==='AVAILABLE'?'primary':'secondary',j.status==='AVAILABLE'?'':'disabled')}</article>`).join(''):'<div class="empty">No assignments generated. Use Refresh AI job board above.</div>'}</div><aside class="panel"><h3>Assignment briefing</h3><p>Select an opportunity to have AI expand it into a complete mission with operational tasking, tail research and airport research. Job Board assignments do not become fully generated dispatch missions until selected.</p>${pill(`${state.jobs.filter(j=>j.status==='AVAILABLE').length} AVAILABLE`,'good')}</aside></div>`}
function dispatch(){const m=active();if(!m)return '<div class="empty">No mission selected. Build an AI mission first.</div>';const identity=m.aircraft_identity||{},pol=m.mx_policy||{};const airports=m.airport_briefings||[];return `<div class="row spread"><label class="inline-select">MISSION FILE<select id="mission-select">${state.missions.map(x=>`<option value="${esc(x.id)}" ${x.id===m.id?'selected':''}>${esc(x.code)} / ${esc(x.title)}</option>`).join('')}</select></label><div class="row no-print">${btn('research-all','Refresh airport intelligence')}${btn('pdf','Download dispatch PDF','primary')}${btn('delete-mission','Delete','danger')}</div></div><div class="hero mini"><div><div class="eyebrow">MISSION RELEASE / ${esc(m.code)}</div><h2>${esc(m.title)}</h2><p>${esc(m.type)} · ${esc(m.difficulty||'')} · ${m.legs.length} leg(s) · ${esc(m.aircraft)} / ${esc(m.registration)}</p></div>${pill(m.status)}</div><div class="notice">SIMULATION ONLY. Neither AI research nor VATSIM position data constitutes an operational dispatch clearance, approved MEL, verified fuel quote or certified flight performance.</div><div class="two-col spaced">${box('Mission profile',`<p class="lead">${esc(m.mission_profile||m.description)}</p><h4>Operational objectives</h4>${lines(m.objectives)}<h4>Operational constraints</h4>${lines(m.operational_constraints)}${item('Client',m.client)}${item('Crew',m.crew?.join(' / '))}`)}${box('Aircraft identity and reliability',`${item('Model',m.aircraft)}${item('ICAO aircraft type',m.icao_type)}${item('Registration',m.registration)}${item('Registry validation',identity.registration_status||identity.verification)}${item('Manufacture year',identity.manufacture_year)}${item('Aircraft age',nfmt(pol.age_years,'years'))}${item('MX level',m.mx_level)}${item('Scenario reliability index',nfmt(pol.reliability_index,'/100'))}${item('Reliability basis',pol.basis)}<p>${esc(identity.verification_notes||'Awaiting registration research / registry source match.')}</p>${sourceLinks(identity.sources||[])}<div class="row no-print">${btn('research-aircraft','Research / recheck aircraft')}${btn('regen-mx','Generate age-based MX')}</div>`)}</div><h2 class="section-title">Flight legs · fuel · performance · W&B</h2><div class="stack">${m.legs.map(l=>legCard(l,m)).join('')}</div><h2 class="section-title">Complete airport briefings</h2><p class="muted">Includes departure, destination, intermediate and identified alternate fields. Fuel price estimates are clearly distinct from published prices.</p><div class="stack">${airports.map(a=>airportCard(a)).join('')}</div><h2 class="section-title">Aircraft maintenance / MEL / CDL / INOP</h2>${mxCard(m)}<h2 class="section-title">Controlled mission documents / payload</h2><div class="two-col">${box('Required / mission-specific documents',lines(m.documents))}${box('Manifests and tasking',`<h4>Passengers</h4>${m.manifest?.length?m.manifest.map(x=>item(x.name,x.role)).join(''):'<p class="muted">No passengers</p>'}<h4>Cargo</h4>${m.cargo?.length?m.cargo.map(x=>item(x.description,nfmt(x.weight_lb,'lb'))).join(''):'<p class="muted">No cargo</p>'}`)}</div>${box('Research completion and stage audit',progressReport(m)+(Object.keys(m.research_audit||{}).length?`<div class="audit-grid">${Object.entries(m.research_audit).map(([k,v])=>`<div class="audit"><b>${esc(k)}</b><span>${esc(v.status||v.error||v.completed_at||'DONE')}</span></div>`).join('')}</div>`:''))}`}
function legCard(l,m){const p=l.planning||{},f=p.fuel_release||{},t=p.told||{},w=p.weight_balance||{};return `<section class="panel leg-panel"><div class="row spread"><div><div class="eyebrow">LEG ${l.seq} / FLIGHT PLANNING</div><h3 class="leg-route">${esc(l.origin)} <span>→</span> ${esc(l.destination)} ${l.alternate_icao?`<small>ALT ${esc(l.alternate_icao)}</small>`:''}</h3></div><div class="row">${pill(l.planning_status||'RESEARCH PENDING','pending')}<button class="small-btn no-print" data-leg="${esc(l.seq)}">Research leg</button></div></div><div class="summary-chips">${pill(nfmt(l.distance_nm,'NM'))}${pill(nfmt(p.flight_time_hr||l.flight_time_hr,'HR'))}${pill(fmt(l.departure_utc))}${pill('Payload '+nfmt(l.cargo_lb,'lb'))}</div><p>${esc(l.mission_task)}</p><div class="three-col"><div class="subpanel"><h4>Fuel release / KG</h4>${[['Trip',f.trip_kg],['Taxi',f.taxi_kg],['Contingency',f.contingency_kg],['Alternate',f.alternate_kg],['Reserve',f.reserve_kg],['Extra',f.extra_kg],['Total release',f.total_kg],['Landing',f.landing_kg]].map(([a,b])=>item(a,nfmt(b,'kg'))).join('')}<p class="muted">${esc(f.fuel_assumptions||'AI research pending')}</p></div><div class="subpanel"><h4>Takeoff / landing data</h4>${item('Departure runway',t.departure_runway)}${item('Arrival runway',t.arrival_runway)}${item('TOW',nfmt(t.takeoff_weight_kg,'kg'))}${item('LDW',nfmt(t.landing_weight_kg,'kg'))}${item('Takeoff dist.',nfmt(t.takeoff_distance_m,'m'))}${item('Landing dist.',nfmt(t.landing_distance_m,'m'))}${item('V1 / VR / V2',`${nfmt(t.v1_kt)} / ${nfmt(t.vr_kt)} / ${nfmt(t.v2_kt)}`)}<p class="muted">${esc(t.status||'Research pending')}</p></div><div class="subpanel"><h4>Weight / balance</h4>${item('Payload',nfmt(w.payload_kg,'kg'))}${item('Zero fuel',nfmt(w.zero_fuel_weight_kg,'kg'))}${item('TOW',nfmt(w.takeoff_weight_kg,'kg'))}${item('LDW',nfmt(w.landing_weight_kg,'kg'))}${item('CG',nfmt(w.cg_percent_mac,'% MAC'))}<p class="muted">${esc(w.assumptions||'Awaiting estimates')}</p></div></div><p class="muted">${esc(p.estimate_basis||'Numerical planning pending. Simulation estimates are not AFM-certified.')}</p>${sourceLinks(p.sources)}</section>`}
function airportCard(a){return `<section class="panel airport-panel"><div class="row spread"><div><div class="eyebrow">AIRPORT INTELLIGENCE / ${esc(a.icao)}</div><h3 class="airport-name">${esc(a.name||'Airport briefing')} <span>${esc(a.icao)}</span></h3></div><div class="row">${pill(a.status||'PENDING',a.status==='RESEARCHED'?'good':'pending')}<button class="small-btn no-print" data-airport="${esc(a.icao)}">Research airport</button></div></div><div class="three-col"><div>${item('Location',[a.municipality,a.country].filter(Boolean).join(' / '))}${item('Elevation',nfmt(a.elevation_ft,'ft MSL'))}${item('Coordinates',a.coordinates)}${item('Operating hours',a.operating_hours)}${item('PPR',a.ppr)}${item('Customs',a.customs)}</div><div><h4>Runways</h4>${lines(a.runways)}<h4>Published frequencies</h4>${lines(a.frequencies)}</div><div>${item('Ground handling',a.handling)}${item('Parking',a.parking)}${item('Facilities',a.facilities)}${item('Restrictions',a.limitations)}${item('METAR',a.weather?.raw)}<div class="row no-print">${btn(`wx:${a.icao}`,'Refresh METAR')}</div></div></div><div class="divider"></div><h4>FBOs / ground handlers / airport service providers (${a.fbos?.length||0})</h4><div class="provider-grid">${a.fbos?.length?a.fbos.map(f=>`<div class="provider"><b>${esc(f.name)}</b>${pill(f.provider_type)}${item('On-field status',f.location_status)}${item('Services',f.services)}${item('Contact',f.contact)}${item('Hours',f.hours)}${f.source_url?`<a href="${safeLink(f.source_url)}" target="_blank" rel="noopener noreferrer">Provider source ↗</a>`:''}</div>`).join(''):'<div class="missing">No FBO / handling result yet. Review the research task and retry if needed.</div>'}</div><h4>Fuel availability and price intelligence (${a.fuel?.length||0})</h4>${a.fuel?.length?`<div class="scroll"><table><thead><tr><th>Supplier</th><th>Fuel</th><th>Availability</th><th>Published price</th><th>Simulation estimate</th><th>Price date / source</th></tr></thead><tbody>${a.fuel.map(f=>`<tr><td>${esc(f.provider)}</td><td>${esc(f.grade)}</td><td>${esc(f.availability)}</td><td>${f.published_price!=null?`${nfmt(f.published_price)} ${esc(f.currency)} / ${esc(f.unit)}`:'NOT PUBLIC / REQUEST QUOTE'}</td><td>${f.estimated_price!=null?`SIM EST ${nfmt(f.estimated_price)} ${esc(f.currency)} / ${esc(f.unit)}`:'—'}</td><td>${esc(f.price_date||'NO PUBLIC DATE')} ${f.source_url?`<a href="${safeLink(f.source_url)}" target="_blank" rel="noopener noreferrer">SOURCE ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="missing">Fuel supplier research pending or no confirmed public listing. A real-time quote cannot be inferred from missing public data.</div>'}${a.unverified_items?.length?`<p class="muted">Outstanding: ${esc(a.unverified_items.join(' · '))}</p>`:''}${a.audit?.missing?.length?`<div class="notice">Research incomplete: ${esc(a.audit.missing.join(', '))}</div>`:''}${sourceLinks(a.sources)}${a.reference_source?`<p class="muted">Aerodrome reference: ${esc(a.reference_source)}</p>`:''}</section>`}
function sourceLinks(s){return s?.length?`<div class="sources"><b>Sources</b>${s.slice(0,15).map(x=>`<a href="${safeLink(x)}" target="_blank" rel="noopener noreferrer">${esc(x)}</a>`).join('')}</div>`:''}
function mxCard(m){const report=m.mx_report||{},mx=m.maintenance||[],policy=m.mx_policy||{};return `<div class="panel"><div class="row spread">${pill(m.mx_level||'OK')}${pill(`SIM RELIABILITY INDEX ${nfmt(policy.reliability_index,'/100')}`)}${btn('regen-mx','Regenerate maintenance scenario')}</div><p>${esc(report.overview||'AI maintenance scenario not yet returned.')}</p><p class="muted">${esc(report.reliability_assessment||policy.basis||'')}</p>${mx.length?mx.map((d,i)=>`<div class="defect"><div class="row spread"><h4>DEFECT ${i+1} — ${esc(d.item)}</h4>${pill(d.category)}</div>${item('Symptom',d.symptom)}${item('MEL / CDL reference',d.mel_cdl_reference||'NO VERIFIED AIRCRAFT/OPERATOR-SPECIFIC REFERENCE')}${item('Reference confidence',d.reference_status)}${item('Dispatch limitation',d.dispatch_effect)}${item('Operational limits',d.operational_limits)}${item('Rectification',d.rectification)}<h4>MSFS cockpit simulation actions</h4>${lines(d.msfs_actions)}<h4>Crew procedure (simulated)</h4>${lines(d.crew_actions)}${sourceLinks(d.source_url?[d.source_url]:[])}</div>`).join(''):'<div class="notice blue">No active simulated INOP equipment, or MX AI is still in progress. GOOD / younger aircraft can legitimately have zero defects.</div>'}<h4>Inspection notes</h4>${lines(report.inspection_notes)}${sourceLinks(report.sources)}</div>`}
function reliabilityPreview(a){const year=Number(a.manufacture_year),age=Number.isInteger(year)&&year>1930&&year<=new Date().getFullYear()?new Date().getFullYear()-year:null;const ap=state.settings.age_influence&&age!==null?(age>=35?4:age>=25?3:age>=15?2:age>=7?1:0):0;const base={GOOD:-2,OK:0,BAD:3}[a.mx_level||'OK']??0;return {age,index:Math.max(48,Math.min(98,98-Math.max(0,Math.min(7,2+ap+base))*7))}}
function fleet(){return `<div class="two-col">${box('Research an aircraft / registration',`<p class="muted">AI researches public registry identity and manufacture year before creating an aircraft record. A type/registration conflict is shown, not concealed.</p><form id="fleet-form"><label class="block-label">Tail registration (optional)<input name="registration" placeholder="N721RF, G-ABCD, etc."></label><label class="block-label">Aircraft type / ICAO<input name="aircraft" placeholder="BE58, H25B, C25C, etc."></label><label class="block-label">Regional preference<input name="region" placeholder="Optional"></label><label class="block-label">Simulated maintenance condition<select name="mx_level"><option>GOOD</option><option selected>OK</option><option>BAD</option></select></label><button class="btn primary">Research + add aircraft</button></form>`)}${box('Fleet reliability framework',`<p>Each AI-researched aircraft is matched against public data. Manufacture year, where credible, affects a <b>simulation reliability index</b> and the suggested number of INOP/MEL/CDL events.</p><div class="mx-scale"><span>GOOD / less pressure</span><span>OK / moderate</span><span>BAD / more pressure</span></div><p class="muted">The index is a game mechanic, never a real aircraft reliability prediction or airworthiness status.</p>`)}</div><h2 class="section-title">Aircraft registry</h2>${state.fleet.length?`<div class="fleet-grid">${state.fleet.map(a=>`<div class="panel"><div class="row spread"><h3>${esc(a.registration)}</h3>${pill(a.registration_status||'UNVERIFIED')}</div>${item('Model',[a.manufacturer,a.model].filter(Boolean).join(' '))}${item('ICAO type',a.icao_type)}${item('Manufacture year',a.manufacture_year)}${item('Age',nfmt(reliabilityPreview(a).age,'years'))}${item('Sim reliability index',nfmt(reliabilityPreview(a).index,'/100'))}${item('Serial',a.serial_number)}${item('Operator',a.operator)}${item('MX setting',a.mx_level)}<label class="block-label">Set maintenance level<select data-fleet-mx-select="${esc(a.registration)}">${['GOOD','OK','BAD'].map(x=>`<option ${a.mx_level===x?'selected':''}>${x}</option>`).join('')}</select></label>${item('Notes',a.verification_notes)}${sourceLinks(a.sources)}<div class="row"><button class="small-btn" data-fleet-mx="${esc(a.registration)}">Change MX</button><button class="small-btn" data-fleet-recheck="${esc(a.registration)}">Recheck tail</button><button class="small-btn red" data-fleet-remove="${esc(a.registration)}">Remove</button></div></div>`).join('')}</div>`:'<div class="empty">No verified or researched aircraft profiles saved. Add a tail or type above.</div>'}`}
function flight(){const m=active(),l=state.live,fp=l?.pilot?.flight_plan||{};return `<div class="two-col">${box('VATSIM connection monitor',`<div class="row spread">${pill(l?.status||'NO FEED',l?.status==='ONLINE'?'good':'pending')}${btn('refresh-vatsim','Refresh network feed')}</div>${item('Configured CID',state.settings.vatsim_cid||'SET IN SETTINGS')}${item('Callsign',l?.pilot?.callsign)}${item('Aircraft',fp.aircraft_short||fp.aircraft)}${item('Departure',fp.departure)}${item('Destination',fp.arrival)}${item('Alternate',fp.alternate)}${item('Current altitude',nfmt(l?.pilot?.altitude,'ft'))}${item('Groundspeed',nfmt(l?.pilot?.groundspeed,'kt'))}${item('Heading',nfmt(l?.pilot?.heading,'°'))}${item('Position',l?.pilot?`${l.pilot.latitude}, ${l.pilot.longitude}`:null)}${item('Feed updated',fmt(l?.feed_timestamp))}${item('Flight plan route',fp.route)}<div class="notice blue">VATSIM provides real-time snapshots, not a certified flight track or complete historical log. This app records observed sessions in browser storage while open.</div>`)}${box('Mission progress / simulator',`${m?`<h3>${esc(m.code)}</h3><p>${esc(m.title)}</p>${item('Mission route',m.legs?.map(l=>l.origin).slice(0,1).concat(m.legs.map(l=>l.destination)).join(' → '))}<div class="row">${['PLANNING','RESEARCHING','READY','AIRBORNE','COMPLETED'].map(x=>`<button class="small-btn ${m.status===x?'selected':''}" data-mission-status="${x}">${x}</button>`).join('')}</div>`:'<p class="muted">No saved mission selected.</p>'}<div class="notice">Mission status is user-controlled SIMULATION progress. VATSIM connection alone does not mark a flight as landed or completed.</div>`)}</div>`}
function logbook(){return `<div class="hero mini"><div><div class="eyebrow">FLIGHT RECORDING / VATSIM</div><h2>Observed network sessions</h2><p>CID ${esc(state.settings.vatsim_cid||'NOT SET')} · ${state.logbook.length} locally captured sessions</p></div>${btn('refresh-vatsim','Refresh live CID','primary')}</div>${box('VATSIM flight session journal',state.logbook.length?`<div class="scroll"><table><thead><tr><th>Callsign</th><th>Flight plan</th><th>Seen (UTC)</th><th>Max altitude</th><th>Max GS</th><th>State</th></tr></thead><tbody>${state.logbook.map(x=>`<tr><td><b>${esc(x.callsign)}</b><small>${esc(x.aircraft||'—')}</small></td><td>${esc(x.departure||'—')} → ${esc(x.arrival||'—')}<small>${esc(x.alternate?'ALT '+x.alternate:'')}</small></td><td>${fmt(x.first_seen)}<small>Last: ${fmt(x.last_seen)}</small></td><td>${nfmt(x.max_altitude_ft,'ft')}</td><td>${nfmt(x.max_groundspeed_kt,'kt')}</td><td>${pill(x.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No VATSIM sessions observed. Enter your CID in Settings, then keep the app open during a flight to record snapshots.</div>')}${box('Data integrity notes',`<p class="muted">Official VATSIM's public Data API only identifies currently connected pilots and their filed flight plans. Departure/arrival shown here are <b>filed plan airports</b>, not confirmed landing events. A disconnect is marked last observed, not landed; history cannot be reconstructed for periods the app was closed. This is not a regulatory logbook.</p><div class="row">${btn('export-logbook','Export flight records')}${btn('clear-logbook','Clear journal','danger')}</div>`)}`}
function settings(){return `<div class="two-col">${box('Configuration',`<form id="settings-form"><label class="block-label">VATSIM CID (your network ID)<input name="vatsim_cid" inputmode="numeric" maxlength="9" pattern="[0-9]{5,9}" value="${esc(state.settings.vatsim_cid)}" placeholder="1234567"></label><p class="muted">Used for reading the public live feed. Your CID is stored only in this browser's settings.</p><label class="block-label">App access PIN (if configured on Render)<input type="password" autocomplete="off" name="access_pin" value="${esc(state.settings.access_pin||'')}" placeholder="Optional APP_ACCESS_PIN value"></label><label class="block-label">Default home base / region<input name="home_base" value="${esc(state.settings.home_base||'')}" placeholder="ENGM or Miami, Florida"></label><label class="block-label">Default maintenance level<select name="mx_default">${['GOOD','OK','BAD'].map(x=>`<option ${state.settings.mx_default===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="age_influence" ${state.settings.age_influence?'checked':''}> Simulate age-sensitive aircraft reliability</label><button class="btn primary">Save configuration</button></form>`)}${box('Backend health & diagnostic log',`${item('Backend',health.ok?'ONLINE':'UNREACHABLE')}${item('Release',health.version)}${item('AI backend',health.aiConfigured?'OPENAI_API_KEY CONFIGURED':'API KEY MISSING')}${item('AI model',health.model)}${item('Access PIN required',health.pinRequired?'YES':'NO')}${item('Persistent storage','THIS BROWSER ONLY')}<div class="row">${btn('refresh-health','Check services')}${btn('refresh-debug','Refresh debug')}</div><pre id="debug-log" class="debug">Open the debug log to see AI stage failures.</pre><div class="notice">If AI is enabled and this Render service is public, API use can incur OpenAI charges. Set APP_ACCESS_PIN in Render for basic access control; use proper authentication for multi-user deployment.</div>`)}</div>${box('Backups and migration',`<p>Export saved missions, researched airports, fleet identities, AI task states and VATSIM logbook. Import replaces the local app database after confirmation. This rebuild can import its own backups; older PATCH47 databases require a separate conversion.</p><div class="row">${btn('export','Download backup')}${btn('import','Import backup')}${btn('clear-tasks','Clear finished tasks')}</div><input type="file" hidden id="import-file" accept="application/json"></input><p class="muted">The app automatically adopts the prior ground-up v2 browser database if it is stored under its existing key. It does not silently overwrite PATCH47 storage.</p>`)}`}
const views={dashboard,builder,jobs,dispatch,fleet,flight,logbook,settings};
function bindTasks(){}
function bindView(){const mf=$('#mission-form');if(mf)mf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(mf));d.age_influence=mf.elements.age_influence.checked;delete d.fleet_registration;d.route=d.route.trim()?d.route.trim().toUpperCase().split(/[\s,;>→-]+/).filter(Boolean):[];if(!d.leg_count)delete d.leg_count;queue('mission',d,null,null,'AI mission creation');toast('Mission research queued. You can navigate while AI works.')};const fs=$('#fleet-select');if(fs)fs.onchange=()=>{const a=state.fleet.find(x=>x.registration===fs.value);if(!a)return;mf.elements.aircraft.value=a.model||a.icao_type||a.manufacturer||'';mf.elements.registration.value=a.registration;mf.elements.mx_level.value=a.mx_level||'OK'};const sf=$('#settings-form');if(sf)sf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(sf));d.vatsim_cid=d.vatsim_cid.trim();if(d.vatsim_cid&&!/^\d{5,9}$/.test(d.vatsim_cid))return toast('CID must contain 5–9 digits');d.age_influence=sf.elements.age_influence.checked;state.settings={...state.settings,...d};save();layout();refreshHealth();refreshVatsim();toast('Settings saved')};const ff=$('#fleet-form');if(ff)ff.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(ff));if(!d.aircraft&&!d.registration)return toast('Enter an aircraft model or registration');queue('aircraft',d,null,'fleet','Research aircraft '+(d.registration||d.aircraft))};const ms=$('#mission-select');if(ms)ms.onchange=()=>{state.selected=ms.value;save();layout()};const job=$('#job-form');if(job)job.onsubmit=e=>e.preventDefault();const imp=$('#import-file');if(imp)imp.onchange=async()=>{try{const d=JSON.parse(await imp.files[0].text());if(!Array.isArray(d.missions)||!Array.isArray(d.jobs)||!Array.isArray(d.fleet))throw Error('Not a supported AeroMission backup');if(!confirm('Replace this device’s saved mission data with the imported backup?'))return;state={...blank(),...d,settings:{...blank().settings,...d.settings}};save();layout();toast('Backup restored')}catch(e){toast(e.message)}}}
function bind(){bindView()}
function queue(kind,payload,target=null,key=null,label=''){const repeat=state.tasks.find(t=>(t.state==='QUEUED'||t.state==='RUNNING')&&t.kind===kind&&t.target===target&&t.key===key&&kind!=='mission'&&kind!=='jobs'&&JSON.stringify(t.payload)===JSON.stringify(payload));if(repeat)return repeat;const t={id:uid(),kind,payload,target,key,label:label||kind.toUpperCase(),state:'QUEUED',phase:'research',job_id:null,created_at:new Date().toISOString(),updated_at:null,error:null};state.tasks.push(t);save();updateTasks();void processQueue();return t;}
async function launchTask(t){t.state='RUNNING';save();updateTasks();try{const x=await api('/api/ai/start',{kind:t.kind,payload:t.payload});t.job_id=x.job_id;t.phase=x.phase||'research';t.updated_at=new Date().toISOString();event('AI research launched: '+t.label)}catch(e){taskError(t,e)}finally{save();updateTasks()}}
function taskError(t,e){t.state='ERROR';t.error=e.message||String(e);t.updated_at=new Date().toISOString();event(t.label+': '+t.error,'ERROR');const target=state.missions.find(x=>x.id===t.target);if(target){target.research_audit=target.research_audit||{};target.research_audit[`${t.kind}:${t.key}`]={status:'FAILED',error:t.error,at:new Date().toISOString()};if(t.kind==='airport'){const field=target.airport_briefings?.find(x=>x.icao===t.key);if(field&&field.status!=='RESEARCHED')field.status='FAILED'}}toast(t.label+' failed: '+t.error);if(t.kind==='aircraft'&&t.target&&t.key!=='fleet'){const m=state.missions.find(x=>x.id===t.target);if(m)queue('mx',mxInput(m),m.id,'mx','Maintenance scenario / '+m.code)}}
let pumpBusy=false;
async function processQueue(){if(pumpBusy)return;pumpBusy=true;try{const launching=state.tasks.filter(t=>t.state==='RUNNING').length;const launchable=state.tasks.filter(t=>t.state==='QUEUED').slice(0,Math.max(0,2-launching));await Promise.all(launchable.map(launchTask));const pollable=state.tasks.filter(t=>t.state==='RUNNING'&&t.job_id);await Promise.all(pollable.map(async t=>{try{const x=await api('/api/ai/poll',{kind:t.kind,job_id:t.job_id,phase:t.phase,payload:t.payload});t.updated_at=new Date().toISOString();if(x.phase==='interpretation'){t.job_id=x.job_id;t.phase='interpretation';t.audit=x.audit;event('Web research complete: '+t.label)}else if(x.status==='completed'&&x.phase==='complete'){t.state='DONE';t.phase='complete';t.error=null;applyResult(t,x.data);event('Structured research complete: '+t.label)}else if(['queued','in_progress'].includes(x.status)){t.phase=x.phase||t.phase}else if(x.status==='failed'){throw Error(x.error||'AI provider failed')}updateReadiness();save()}catch(e){taskError(t,e)}}));save();updateTasks();updateView();}finally{pumpBusy=false}}
function updateReadiness(){for(const m of state.missions){if(!['RESEARCHING','PARTIAL RESEARCH'].includes(m.status))continue;const related=state.tasks.filter(t=>t.target===m.id);if(!related.length||related.some(t=>['QUEUED','RUNNING'].includes(t.state)))continue;m.status=related.some(t=>t.state==='ERROR')?'PARTIAL RESEARCH':'READY FOR SIM REVIEW'}}
function mxInput(m){return {registration:m.registration,aircraft:m.aircraft,icao_type:m.icao_type,manufacture_year:m.aircraft_identity?.manufacture_year??null,mx_level:m.mx_level||'OK',age_influence:m.age_influence!==false,mission_type:m.type,mission_profile:m.mission_profile?.slice(0,1000)}}
function flightInput(m,l){return {aircraft:m.aircraft,icao_type:m.icao_type,registration:m.registration,origin:l.origin,destination:l.destination,alternate_icao:l.alternate_icao,distance_nm:l.distance_nm,flight_time_hr:l.flight_time_hr,passengers:l.passengers,cargo_lb:l.cargo_lb,mission_type:m.type,mx_level:m.mx_level,existing_airport_notes:(m.airport_briefings||[]).filter(a=>[l.origin,l.destination].includes(a.icao)).map(a=>({icao:a.icao,runways:a.runways?.slice(0,5),elevation_ft:a.elevation_ft})),leg_seq:l.seq}}
function applyResult(t,data){if(t.kind==='mission'){state.missions.push(data);state.selected=data.id;state.view='dispatch';if(t.key&&String(t.key).startsWith('job:')){const j=state.jobs.find(x=>x.id===t.key.slice(4));if(j)j.status='ASSIGNED'}for(const a of data.airport_briefings){void airportReference(data.id,a.icao);void getWeather(data.id,a.icao);queue('airport',{icao:a.icao},data.id,a.icao,`Airport ${a.icao} / FBO and fuel`)}for(const l of data.legs)queue('leg',flightInput(data,l),data.id,String(l.seq),`Leg ${l.seq} fuel / performance`);queue('aircraft',{registration:data.registration==='UNRESOLVED'?'':data.registration,aircraft:data.aircraft,icao_type:data.icao_type,region:data.legs[0].origin},data.id,'identity','Aircraft registration / identity');toast(`Mission ${data.code} generated. Research queued for every airport and leg.`);layout();return;}
 if(t.kind==='jobs'){state.jobs=data.jobs||[];if(data.warnings?.length)toast(data.warnings.join(' '));toast(`${state.jobs.length} AI assignments loaded`);return;}
 if(t.kind==='aircraft'){
  if(t.key==='fleet'||!t.target){const prev=state.fleet.find(x=>x.registration===data.registration);const v={...data,mx_level:t.payload.mx_level||prev?.mx_level||'OK'};if(prev)Object.assign(prev,v);else state.fleet.push(v);toast('Aircraft research saved: '+data.registration);return}
  const m=state.missions.find(x=>x.id===t.target);if(!m)return;m.research_audit=m.research_audit||{};m.research_audit['aircraft:identity']={status:'COMPLETED',at:new Date().toISOString(),registry_status:data.registration_status};m.aircraft_identity=data;if(data.registration_status==='SOURCE_MATCH'&&data.registration)m.registration=data.registration;
  if(data.icao_type)m.icao_type=data.icao_type;if(data.model&&(!m.aircraft||m.aircraft==='UNRESOLVED'))m.aircraft=data.model;
  const prev=state.fleet.find(x=>x.registration===m.registration);if(prev)Object.assign(prev,{...data,mx_level:m.mx_level});else state.fleet.push({...data,mx_level:m.mx_level});queue('mx',mxInput(m),m.id,'mx','MEL / CDL / MSFS maintenance');return;
 }
 const m=state.missions.find(x=>x.id===t.target);if(!m)return;
 m.research_audit=m.research_audit||{};m.research_audit[`${t.kind}:${t.key}`]={status:'COMPLETED',completed_at:new Date().toISOString(),audit:data.audit||t.audit||null};
 if(t.kind==='airport'){const a=m.airport_briefings.find(x=>x.icao===t.key);if(a)mergeAirport(a,data);else m.airport_briefings.push({...data,icao:t.key});return;}
 if(t.kind==='leg'){const l=m.legs.find(x=>String(x.seq)===String(t.key));if(l){l.planning=data;l.planning_status='SIMULATION ESTIMATE'}return;}
 if(t.kind==='mx'){m.maintenance=data.defects||[];m.mx_report=data;m.mx_policy=data.policy||m.mx_policy;return;}
}
function mergeAirport(existing,research){for(const [k,v] of Object.entries(research)){if(['icao','weather','reference_source','reference_updated_at'].includes(k))continue;if(v!==null&&v!==undefined&&v!==''&&(!Array.isArray(v)||v.length))existing[k]=v;}existing.updated_at=new Date().toISOString()}
async function airportReference(id,code){try{const x=await api(`/api/airport/${code}/reference`);const a=state.missions.find(m=>m.id===id)?.airport_briefings.find(a=>a.icao===code);if(!a||!x.facts?.found)return;const f=x.facts;a.name=a.name||f.name;a.municipality=a.municipality||f.municipality;a.country=a.country||f.country;a.elevation_ft=a.elevation_ft??(+f.elevation_ft||null);a.coordinates=a.coordinates||[f.latitude,f.longitude].filter(Boolean).join(', ');if(!a.runways?.length)a.runways=f.runways||[];if(!a.frequencies?.length)a.frequencies=f.frequencies||[];a.reference_source=f.source;a.reference_updated_at=f.retrieved_at;if(a.status==='PENDING')a.status='REFERENCE LOADED';save();updateView()}catch(e){event(code+' aerodrome reference: '+e.message,'WARN')}}
async function getWeather(id,code){try{const w=await api(`/api/weather/${code}`);const a=state.missions.find(m=>m.id===id)?.airport_briefings.find(a=>a.icao===code);if(a){a.weather=w;save();updateView()}}catch(e){event(code+' weather: '+e.message,'WARN')}}
function retryTask(id){const t=state.tasks.find(x=>x.id===id);if(t)queue(t.kind,t.payload,t.target,t.key,t.label+' / retry')}
function downloadJson(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),4000)}
async function refreshHealth(){try{health=await api('/api/health');layout()}catch(e){health={ok:false,aiConfigured:false};toast(e.message)}}
function recordPilot(pilot){const now=new Date().toISOString(),key=`${pilot.cid}:${pilot.callsign}:${pilot.logon_time||pilot.flight_plan?.departure||'session'}`,fp=pilot.flight_plan||{},entry=state.logbook.find(x=>x.key===key);if(entry){entry.last_seen=now;entry.max_altitude_ft=Math.max(entry.max_altitude_ft||0,pilot.altitude||0);entry.max_groundspeed_kt=Math.max(entry.max_groundspeed_kt||0,pilot.groundspeed||0);entry.observation_count=(entry.observation_count||0)+1;entry.status='ONLINE / OBSERVED'}else state.logbook.unshift({key,source:'PUBLIC VATSIM LIVE DATA',cid:String(pilot.cid),callsign:pilot.callsign,aircraft:fp.aircraft_short||fp.aircraft||'',departure:fp.departure||'',arrival:fp.arrival||'',alternate:fp.alternate||'',route:fp.route||'',session_start:pilot.logon_time||now,first_seen:now,last_seen:now,max_altitude_ft:pilot.altitude||null,max_groundspeed_kt:pilot.groundspeed||null,observation_count:1,status:'ONLINE / OBSERVED',actual_arrival_unverified:true});state.logbook=state.logbook.slice(0,250)}
async function refreshVatsim(){const cid=state.settings.vatsim_cid;if(!cid||vatsimBusy)return;vatsimBusy=true;try{const x=await api(`/api/vatsim/live?cid=${encodeURIComponent(cid)}`);state.live=x;if(x.pilot)recordPilot(x.pilot);else state.logbook.forEach(l=>{if(l.cid===cid&&l.status==='ONLINE / OBSERVED')l.status='OFFLINE — LAST OBSERVED (NOT LANDED)'});save();if(state.view==='flight'||state.view==='logbook')updateView()}catch(e){state.live={status:'FEED UNAVAILABLE',error:e.message};event('VATSIM: '+e.message,'WARN');save()}finally{vatsimBusy=false}}
async function downloadPdf(){const m=active();if(!m)return toast('No mission selected');const issues=(m.airport_briefings||[]).filter(a=>a.status!=='RESEARCHED').map(a=>a.icao);if(issues.length&&!confirm(`AI airport research is incomplete for ${issues.join(', ')}. Export a clearly marked PARTIAL simulation briefing anyway?`))return;try{await openPdf(m,state.settings.access_pin);toast('Dispatch package PDF downloaded')}catch(e){toast('PDF creation failed: '+e.message)}}
async function debug(){try{const d=await api('/api/debug');const x=$('#debug-log');if(x)x.textContent=(d.events||[]).slice(0,50).map(a=>`${a.time} ${a.level.padEnd(8)} ${a.event} ${a.detail}`).join('\n')||'No server events yet'}catch(e){const x=$('#debug-log');if(x)x.textContent='Debug error: '+e.message}}
async function handleAction(name){if(name==='go-builder')state.view='builder';else if(name==='go-dispatch')state.view='dispatch';else if(name==='generate-jobs'){const f=$('#job-form'),d=f?Object.fromEntries(new FormData(f)):{};queue('jobs',{...d,count:6},null,null,'AI Job Board / 6 jobs');toast('AI job discovery queued');return;}else if(name.startsWith('accept:')){const j=state.jobs.find(x=>x.id===name.slice(7));if(j)queue('mission',{title:j.title,type:j.type,route:j.route,aircraft:j.aircraft,registration:j.registration,mx_level:j.mx_level,notes:j.mission_profile+' '+j.description,job_brief:j.brief},null,'job:'+j.id,'Mission from '+j.title);return;}else if(name==='research-all'){const m=active();if(m)for(const a of m.airport_briefings){queue('airport',{icao:a.icao},m.id,a.icao,'Airport '+a.icao+' / refresh');void airportReference(m.id,a.icao);void getWeather(m.id,a.icao)}return;}else if(name==='research-aircraft'){const m=active();if(m)queue('aircraft',{registration:m.registration==='UNRESOLVED'?'':m.registration,aircraft:m.aircraft,icao_type:m.icao_type},m.id,'identity','Aircraft registration / recheck');return;}else if(name==='regen-mx'){const m=active();if(m)queue('mx',mxInput(m),m.id,'mx','Maintenance scenario / '+m.code);return;}else if(name==='pdf'){await downloadPdf();return;}else if(name==='delete-mission'){const m=active();if(m&&confirm(`Delete mission ${m.code} locally?`)){state.missions=state.missions.filter(x=>x.id!==m.id);state.tasks=state.tasks.filter(t=>t.target!==m.id);state.selected=state.missions[0]?.id||null}}else if(name==='refresh-vatsim'){await refreshVatsim();toast(state.live?.status||'VATSIM refreshed');return;}else if(name==='refresh-debug'){await debug();return;}else if(name==='refresh-health'){await refreshHealth();return;}else if(name==='export'){downloadJson(state,'aeromission-ops-3-backup.json');return;}else if(name==='import'){$('#import-file')?.click();return;}else if(name==='export-logbook'){downloadJson(state.logbook,'aeromission-vatsim-observed-logbook.json');return;}else if(name==='clear-logbook'){if(confirm('Erase the locally recorded VATSIM sessions?'))state.logbook=[];}else if(name==='clear-tasks'){state.tasks=state.tasks.filter(t=>!['DONE','ERROR'].includes(t.state));}else if(name.startsWith('wx:')){const m=active();if(m)void getWeather(m.id,name.slice(3));return;}else return;save();layout()}
document.addEventListener('click',e=>{const navBtn=e.target.closest('[data-nav]');if(navBtn){state.view=navBtn.dataset.nav;save();layout();return}const action=e.target.closest('[data-action]');if(action){void handleAction(action.dataset.action);return}const sel=e.target.closest('[data-select-mission]');if(sel){state.selected=sel.dataset.selectMission;state.view='dispatch';save();layout();return}const ap=e.target.closest('[data-airport]');if(ap){const m=active();if(m)queue('airport',{icao:ap.dataset.airport},m.id,ap.dataset.airport,'Airport '+ap.dataset.airport+' / FBO & fuel');return}const leg=e.target.closest('[data-leg]');if(leg){const m=active(),l=m?.legs.find(x=>String(x.seq)===leg.dataset.leg);if(l)queue('leg',flightInput(m,l),m.id,String(l.seq),'Leg '+l.seq+' planning');return}const retry=e.target.closest('[data-retry]');if(retry){retryTask(retry.dataset.retry);return}const status=e.target.closest('[data-mission-status]');if(status){const m=active();if(m){m.status=status.dataset.missionStatus;save();layout()}return}const remove=e.target.closest('[data-fleet-remove]');if(remove){if(confirm('Remove '+remove.dataset.fleetRemove+' from the local roster?')){state.fleet=state.fleet.filter(x=>x.registration!==remove.dataset.fleetRemove);save();layout()}return}const recheck=e.target.closest('[data-fleet-recheck]');if(recheck){const a=state.fleet.find(x=>x.registration===recheck.dataset.fleetRecheck);if(a)queue('aircraft',{registration:a.registration,aircraft:a.model},null,'fleet','Recheck '+a.registration);return}const fm=e.target.closest('[data-fleet-mx]');if(fm){const a=state.fleet.find(x=>x.registration===fm.dataset.fleetMx);if(a){a.mx_level=({GOOD:'OK',OK:'BAD',BAD:'GOOD'})[a.mx_level||'OK'];for(const m of state.missions.filter(m=>m.registration===a.registration)){m.mx_level=a.mx_level;queue('mx',mxInput(m),m.id,'mx','MX updated / '+m.code)}save();layout();toast(a.registration+' MX level: '+a.mx_level+'; matching missions updated')}return}});
document.addEventListener('change',e=>{const sel=e.target.closest?.('[data-fleet-mx-select]');if(!sel)return;const a=state.fleet.find(x=>x.registration===sel.dataset.fleetMxSelect);if(!a)return;a.mx_level=sel.value;for(const m of state.missions.filter(m=>m.registration===a.registration)){m.mx_level=a.mx_level;queue('mx',mxInput(m),m.id,'mx','MX updated / '+m.code)}save();layout();toast(a.registration+' simulated MX: '+a.mx_level)});
window.addEventListener('storage',e=>{if(e.key===STORE){toast('Local data changed in another tab. Refresh to see the latest state.')}});
layout();void refreshHealth();if(state.settings.vatsim_cid)void refreshVatsim();setInterval(()=>{void processQueue()},5000);setInterval(()=>{if(state.settings.vatsim_cid)void refreshVatsim()},90000);if(known().length)void processQueue();
